import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
            S = next(iterator)
            A = next(iterator)
        except StopIteration:
            break

        S_list = list(S)
        chars = ['a', 'b', 'c', 'd', 'e']

        if M > N:
            for i in range(N):
                if S_list[i] == '?':
                    S_list[i] = 'a'
            results.append("".join(S_list))
            continue

        best_S = None

        for candidate_char in chars:
            temp_S = S_list[:]
            filled = False
            for i in range(N):
                if temp_S[i] == '?':
                    temp_S[i] = candidate_char
                    filled = True

            j = 0
            for i in range(N):
                if temp_S[i] != '?' and temp_S[i] == A[j]:
                    j += 1
                    if j == M:
                        break

            if j < M:
                best_S = "".join(temp_S)
                break

        if best_S is not None:
            results.append(best_S)
        else:
            results.append("-1")

    print("\n".join(results))

if __name__ == "__main__":
    solve()
